    seoText: `<h2>About data storage conversions</h2>
      <p>Data storage conversions are essential for understanding file sizes, storage capacity, and data transfer rates. The two systems used are decimal (powers of 1,000) and binary (powers of 1,024).</p>
      <p>In the decimal system (SI standard): 1 KB = 1,000 bytes, 1 MB = 1,000,000 bytes, 1 GB = 1,000,000,000 bytes. In the binary system used by operating systems: 1 KiB = 1,024 bytes, 1 MiB = 1,048,576 bytes, 1 GiB = 1,073,741,824 bytes. This difference explains why a "500 GB" hard drive shows as less in Windows or macOS.</p>
      <p>For the international definition, see the <a href="https://www.nist.gov/pml/owm/si-units-information" target="_blank" rel="noopener noreferrer">NIST reference on units of information</a>.</p>`,
